questions.starter_code:
const config = { retries: 0 };
const retries = config.retries || 3;
console.log(retries); // 3 — should be 0

questions.answer:
Use nullish coalescing:

const config = { retries: 0 };
const retries = config.retries ?? 3;
console.log(retries); // 0

`||` treats every falsy value as missing, including 0 and "". `??` only falls back when the left side is `null` or `undefined`, so a legitimate 0 survives.

questions.starter_code:
function getCity(response) {
  // response?.user?.address?.city ...
}

console.log(getCity({ user: { address: { city: "Pune" } } }));
console.log(getCity({ user: null }));

questions.answer:
function getCity(response) {
  return response?.user?.address?.city ?? "unknown";
}

console.log(getCity({ user: { address: { city: "Pune" } } })); // "Pune"
console.log(getCity({ user: null }));                            // "unknown"
console.log(getCity(undefined));                                 // "unknown"

`?.` short-circuits the rest of the chain and yields `undefined` instead of throwing; `??` then supplies the fallback.

questions.starter_code:
function grade(score) {
  // return "A", "B", or "C"
}

console.log(grade(95), grade(72), grade(40));

questions.answer:
function grade(score) {
  return score >= 90 ? "A" : score >= 60 ? "B" : "C";
}

console.log(grade(95), grade(72), grade(40)); // A B C

The conditional operator is right-associative, so the second `? :` belongs to the false branch of the first. Add parentheses if the nesting grows beyond two levels.
